def invert(root):
    if root is None:
        return None
    work = [root]
    while work:
        node = work.pop()
        node.left, node.right = node.right, node.left
        if node.left is not None:
            work.append(node.left)
        if node.right is not None:
            work.append(node.right)
    return root
